n.exploreUrl:
@js:
   let result=[];
   let push=(title, url, size)=>result.push({
       "title": title,
       "url": url,
       "style": {
        "layout_flexGrow": 1,
        "layout_flexBasisPercent": size
       }
});
   bu="https://m.zztxt.net/xiaoshuodaquan";
   aj=java.ajax(bu);
   let a=org.jsoup.Jsoup.parse(aj);
   let b=a.select('.categories ul li a');
   for (i in b) {
        let url=String(b[i].attr('href'));
        url=url+"<,/page_{{page}}.html>";
        push(b[i].text(), url, 0.25);
    }
JSON.stringify(result);

